import {castSceneV39} from './cast-v39.js';
// Original workplace branches developed from the Captain's admin/recruitment motifs.
const rows=[
 ['room-capacity','二十五個人，十五個位子','船長確認了二十五人的聚餐，店家卻只留十五人包廂。她說大家坐近一點，你看椅子已經沒有地方再往近走。','位子可以擠，膝蓋能不能先報人數？','用餐人數與座位容量','店家訂位確認','宣布剩下十人是幽靈船員，請店家先替幽靈上一份菜。','幽靈餐沒有出，店家倒是找出可以加開的桌。船長重新核對名單，這次沒有人靠站著證明自己有參加。'],
 ['star-rating','評分很好，翻開只有一顆星','船長說找到一間大家會喜歡的餐廳，你打開地圖，最新幾則評論都在討論等餐和漏單。她指著店名說照片看起來很好吃。','照片有吃過，還是我們要先試？','餐廳評價與實際需求','近期評論與候選清單','請餐廳照片親自來試菜，吃完再替真人訂位。','照片沒有長嘴，你們改查可容納人數、價格和出餐時間。船長保留兩間候選，晚餐不再只靠濾鏡決定。'],
 ['coffee-flies','咖啡渣比大家更早繁殖','茶水間的濕咖啡渣放了幾天，小飛蟲已經組成迎賓隊。船長問要買什麼除蟲，你看見垃圾袋旁還有一整桶水。','先處理濕掉的源頭，別只打空軍。','咖啡渣處理與清潔頻率','值日與清運表','替果蠅開員工編號，滿三天就請牠們繳咖啡費。','果蠅沒有付錢，濕渣倒是當天清掉。船長補上清運頻率，茶水間終於不是唯一會自行招募的部門。',['admin','hr']],
 ['job-description','104寫行政，報到先接人資','船長拿來一份徵才稿，標題寫行政專員，工作清單卻把招募、考勤和勞健保全包進去。她問還缺什麼，你想先問這到底缺幾個人。','標題只有一行，工作不能無限往下加吧。','職稱與實際工作範圍','主管確認的JD','把JD印成登機證，超過一個職務就請公司補買座位。','登機證印了一長條，你們才把必做、協作和另需人力的項目分開。船長發出去的徵才稿，終於不用等報到才解釋第二個職位。',['admin','hr']],
 ['hr-coffee','人資面談中，咖啡也在等人資','船長剛要開始面談，訊息又叫她準備會議咖啡。兩邊都寫現在，她問你是不是該在自己的行事曆裡安排一位助理船長。','咖啡還沒泡，候選人已經坐好了。','招募面談與接待分工','當日時段與代理表','讓咖啡機自己當面試官，第一題問能不能承受高壓。','咖啡機只吐出蒸氣。你們請會議主辦自行安排飲料，船長留在面談現場，候選人今天沒有對著空椅子介紹自己。',['hr','admin']],
 ['floor-plan','土木系不是免費室內設計套餐','船長聽說同事念過土木，立刻帶著新辦公室尺寸來問能不能畫一下。那個一下包括配置、水電和裝潢估價，對方還在看第一張紙。','會看圖，跟可以免費包整間，是兩件事。','專業範圍與委託預算','正式需求與估價','替每張免費圖發建照，要求一下先通過結構審查。','紙建照沒有法律效力，卻讓大家看見這不是一個午休能畫完。船長整理需求去找合適窗口，同事保住自己的下班。',['admin','design']],
 ['camera-permission','監視器裝好了，誰能看還沒問','船長整理新設備清單，監視器已在牆上，使用目的與觀看權限卻留白。阿福說先能用再說，你看那個再說通常沒有日期。','鏡頭先別替權限做決定。','設備用途與存取權限','授權及使用紀錄','給每支鏡頭配一副眼罩，核准之前只准欣賞天花板。','眼罩沒有真的戴上，你們先限制存取再補齊用途與保留期限。船長把交付項目列清楚，能看不再等於誰都可以看。',['admin','mis'],['captain','sonny']],
 ['cola-code','可樂密語，最後只是無糖','船長轉來一句可樂暗號，群組已經猜出三種意思。你拿著採購單問規格，她說就是要買飲料，怎麼突然像在破案。','先問有糖無糖，比破案快吧。','飲料規格與數量','本人確認的訂購單','成立可樂偵探社，第一案追查冰塊失蹤之謎。','偵探社結案得很快：兩箱無糖、一箱一般。船長重新下單，今天沒有把一個飲料名稱變成整天的辦公室傳說。'],
 ['game-help','柯南卡關，行政支援先上線','船長拿手機來問你遊戲怎麼過，旁邊的採購訊息也在跳。你幫她看了第一步，突然被安排成接下來三關的固定窗口。','我幫看一下，不是接整季攻略。','臨時協助與工作優先順序','待辦與約定時間','請柯南先填支援工單，沒有重現步驟不准喊真相。','偵探沒填工單，船長倒是先把採購處理完。你們約好休息時間再看一關，今天的兇手不是整張待辦表。'],
 ['reservation-name','訂位名字對了，人數是上個月','船長帶大家到店，櫃台唸出正確公司名，接著說歡迎八位。隊伍後面還站著十幾個人，訂位單原來沿用了上次。','公司沒換，人數有換。','訂位日期與最新人數','店家回覆紀錄','替舊訂位單辦退休餐會，禁止它繼續代理本月出席名單。','舊單被歸檔，新人數重新確認。船長和店家調整座位，今天不用靠大家假裝只是路過來解決超額。'],
 ['rain-route','Outdoors下雨，備案也在戶外','船長把活動備案寄來，晴天去草地，雨天去另一塊草地。你看氣象圖問差在哪，她指著新的集合點說比較近。','近一點也還是會淋濕。','天候取消條件與室內備案','活動變更通知','替雨雲寄會議邀請，請它選擇不出席。','雨雲沒有回覆，船長換成可容納全員的室內場地。大家收到清楚通知，這趟航程不靠雨衣維持團隊精神。',['admin','hr']],
 ['candidate-map','面試邀請，地址只有舊的','船長問你為什麼候選人還沒到，轉寄信上的地址卻是以前的辦公室。對方已經到了門口，只是到了另一個門口。','人有準時，是地址遲到。','面試地址與聯絡方式','更新後的邀請範本','頒給候選人城市探險家徽章，公司負責出交通補給。','徽章只畫在便條上，你們先致歉並改成方便對方的方式面談。船長更新範本，下位候選人不用靠都市傳說找門。',['hr']],
 ['keys-handover','鑰匙在誰那，變成全公司問答','船長要開櫃子找資料，群組有人記得交給另一個人。你順著訊息追了四次，最後回到同一張抽屜照片。','找得到鑰匙，也要知道上次誰拿。','物品保管與借還方式','交接簽收表','替鑰匙掛航海定位器，漂流超過一天就播海難通知。','鑰匙沒有出海，借還表倒是補上時間和保管人。船長打開櫃子，今天少了一場靠記憶接力的尋寶。',['admin']],
 ['desk-boat','新同事明天來，桌子還在海上','船長說新人明天報到，電腦和座位都請大家先彈性。你問彈性到哪，她把一張會議桌照片傳過來。','報到可以準時，設備不能永遠稍後。','報到設備與座位安排','到職準備清單','讓新同事先登入一張紙電腦，看看主管能不能接受紙成果。','紙鍵盤沒有開機，設備缺項卻當天被看見。船長安排可用的替代機與座位，新人至少不是帶著期待來當熱點。',['admin','hr','mis']],
 ['visitor-badge','訪客證有了，接待人下班了','船長準備好訪客證，對方到樓下才發現會議時間被改，主辦已不在。她問誰可以先接一下，群組只剩三個貼圖。','訪客是約來的，不是抽獎抽中的。','來訪時間與接待主責','雙方確認的會議邀請','讓訪客證代替主辦開場，第一張投影片寫我只是塑膠。','塑膠證沒有主持會議，你們先向對方說明並確認能到場的人。船長更新通知，訪客不再靠群組貼圖猜公司誰有空。',['admin']],
 ['birthday-list','壽星名單比員工名單更新','船長準備慶生餐，名單上有離職同事，也漏了剛到職的人。她問要以哪份為準，你看兩份檔名都寫最新。','蛋糕不能替人事資料驗證。','出席名單與自願慶生意願','當月確認名單','請蛋糕擔任戶政官，蠟燭點名沒答到就先不切。','蛋糕保留原職，船長改請本人確認出席與意願。今天沒有因為一張舊表，讓別人的生日變成自己的尷尬。',['admin','hr']],
 ['lunch-route','訂餐之前，先宣布航線','船長邀幾個人下班吃飯，餐廳已選好，大家卻各以為在不同區。你問要不要先確認，她說搭車一下就到了。','一下是幾站？大家要先知道才答應。','私人聚餐地點與個人意願','各自確認的邀請','用地球儀量通勤，超過半個便當的距離就改開視訊吃。','地球儀轉了半圈，你們換到彼此方便的地方。船長重新問誰願意來，今晚沒有人因為一句都可以就被載去未知海域。',[],[],true],
 ['holiday-form','請假單只差一個簽名，簽名的人休假','船長幫同事追假單，核准人本人已經出國。表單一直停在待處理，系統卻提醒申請人沒有提前完成。','規定有期限，代理也得有名字。','請假流程與核准代理','明確代理紀錄','替簽名欄訂機票，請它飛去找主管本人蓋章。','簽名欄沒有過海關，代理流程倒是補上。船長把卡住的申請交給有權窗口，休假的人不用證明自己能比主管更早回國。',['hr']],
 ['chair-count','椅子少兩張，報名已經截止','船長核對教育訓練，講師、投影機和便當都齊了，座位少兩張。她問站後面可以嗎，你看課程寫三小時實作。','實作可以動手，不必先練站功。','訓練席次與可用設備','現場配置表','設立站著上完可獲船副執照，然後請主管先示範。','船副沒人報名，隔壁的可用椅子很快被借到。船長重新走過一次配置，課程沒有附贈免費腿痠。',['admin','hr']],
 ['uniform-size','尺寸還沒問，團購先結單','船長發訊息說公司衣服已經訂了，請大家回報尺寸。你問下單前用什麼數字，她說大概抓一下比較快。','人不是大概穿得進去就算。','自願訂購與本人尺寸','確認後的訂單','替太小的衣服辦縮骨功培訓，學費請下單前的大概支付。','縮骨課沒有開，船長先問店家可修改的範圍。你們核對本人需求，團購終於不靠同事改變體型收尾。',['admin']],
 ['interview-title','面試行政，問題先問會不會招人','船長替部門安排面試，行政職缺的題目突然變成人資招募。候選人問職稱是不是寫錯，她把徵才頁往上滑了一次。','今天要談哪個工作，先讓對方知道吧。','徵才職稱與面試內容','主管確認的職務說明','請JD出庭作證，問它為什麼錄取前後說不同的話。','JD沒有上證人席，主管倒是補清楚兼任內容。船長把新版寄給候選人，對方能在接受之前決定，而不是報到後才拆驚喜包。',['hr','admin']],
 ['meeting-snacks','零食先到，會議室沒到','船長把點心放在A室，主辦卻已改到B室，兩邊都有人等開場。你看點心車穿過走廊，進度比會議通知還準時。','先找人在哪，再找餅乾去哪。','會議地點與通知版本','統一會議邀請','頒給點心車最佳專案經理獎，只有它知道交付要到現場。','點心車沒有領獎，你們把地點統一。船長送完最後一盤，兩組人終於坐進同一間，不必隔牆共享議程。',['admin']],
 ['parcel-owner','包裹寫公司，收件人叫幫忙','船長收到一箱設備，標籤只有公司名，大家都說可能是別組訂的。你問採購單，群組開始轉傳同一張箱子照片。','箱子不會自己說屬於哪一案。','採購品項與保管窗口','訂單及簽收紀錄','給包裹發臨時員工證，職稱寫待分發主管。','紙員工證貼好，訂單也總算被翻出來。船長交到真正窗口手上，箱子不必靠在走廊待滿試用期才取得歸屬。',['admin','mis']],
 ['exit-checklist','交接清單，離職當天才寄','船長問同事怎麼還沒交完，對方才剛收到十幾項清單。你往寄件時間看，距離下班只剩兩小時。','清單晚到，不能算對方拖了十天。','離職交接項目與合理期限','雙方確認的交接表','替清單配時光機，先回到兩週前再催進度。','時光機沒有啟動，你們先確認今天可完成與需另約的事項。船長補齊通知，交接不再用寄出時間冒充提前告知。',['hr','admin']],
 ['benefits-version','福利寫在網頁，實施寫在口頭','船長被問到職缺上的福利，主管說那是舊版，她手上卻沒有新版。你們開兩個頁面，連每一項的有沒有都對不起來。','對外還看得到，就得說清楚目前是什麼。','福利內容與適用時間','已確認的公開說明','請舊網頁領退休金，新版沒到職前禁止繼續招募期待。','舊頁沒有領錢，錯誤資訊先被修正。船長留下更新日期，候選人不用自己猜哪些字還在上班。',['hr']],
 ['training-search','想學行政，搜尋結果全是救火','船長問公司能不能安排訓練，收到的連結是一串免費教學。工作清單卻要求她獨立處理招募和行政，還要今天學會。','免費可以看，不能拿來代替所有交接。','訓練內容與帶領窗口','可執行的學習安排','幫搜尋引擎升任人資長，請它親自接電話處理例外。','搜尋引擎沒有接任，你們先安排實際操作與可問的人。船長留下問題清單，今天學會的是一個流程，不是如何假裝全部都會。',['hr','admin']],
 ['cleaning-ship','全員大掃除，清潔工具只有兩把','船長號召全員整理辦公室，現場拖把卻只夠兩個人。其他人圍成一圈，場面比清潔更像觀看拖把展。','分區可以先分，工具也要跟著分吧。','清潔分工與可用工具','分區及用品表','售賣拖把特展導覽票，收入全數購買第三把拖把。','導覽沒有開賣，你們先讓有工具的人處理一區，其餘整理各自桌面。船長補齊用品，團隊合作不再等於輪流看別人擦地。',['admin']],
 ['speakerphone','會議通知的通知，要再開一場','船長轉來新流程通知，主管說大家不一定會看，所以請她再安排一場說明通知的會議。你問流程哪天開始，她也在等回答。','先把生效日說完，再決定需不需要占一小時。','流程生效日與需知內容','單頁公告與提問窗口','建立會議通知通知委員會，第一案表決立即解散。','委員會在成立前就散了，你們把三個必要欄位補到公告。船長保留提問方式，大家今天少坐一場只為讀信的會。',['admin','hr']],
 ['late-dinner','續攤航線，先問誰要上船','私人聚餐快結束，船長問大家要不要再去下一間。有兩個人只是點頭道別，卻被一起算進訂位，你看他們已經叫了車。','道別不是報名，先問本人要不要。','續攤意願與各自交通','本人確認的出席名單','下一攤改開離線副本，沒有登入的人一律送回家休息。','離線副本不用訂位。船長重數願意去的人，準備回家的人順利上車，今晚的友情沒有綁最低消費。',[],[],true],
 ['captain-log','船長日誌，終於寫了取消什麼','船長拿著新一版行政排程，前版任務全留下，只多了主管今天想到的內容。她問你先做哪個，兩個人的清單卻各缺一段取消通知。','新航線可以走，先讓舊航線靠港吧。','優先順序與取消項目','主管確認的排程','替每個取消任務升海盜旗，沒插旗不得宣稱已停止。','海盜旗畫滿了白板，主管才選定真正要保留的項目。船長寄出新日誌，這次每個人知道往哪走，也知道哪條不用再追。',['admin','hr']]
];
export const CAPTAIN_EVENTS_V39=rows.map((row,index)=>castSceneV39('captain',index,row));
